from pathlib import Path
import base64,json,subprocess,time
files={'usr/local/lib/f8-pro/sensor-relay.py': '', 'usr/local/lib/f8-pro/sensor-relay-panel.py': ''}
for name,data in files.items():(Path('/')/name).write_bytes(base64.b64decode(data))
pre=['runuser','-u','likimk','--','env','XDG_RUNTIME_DIR=/run/user/1602','DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1602/bus']
subprocess.run(pre+['systemctl','--user','restart','f8-sensor-relay.service'],check=True)
subprocess.run(pre+['systemctl','--user','stop','f8-sensor-relay-panel-fixed-live.service'],capture_output=True)
import json,subprocess,pwd,os
from pathlib import Path
pre=['runuser','-u','likimk','--','env','XDG_RUNTIME_DIR=/run/user/1602','DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1602/bus']
envout=subprocess.check_output(pre+['systemctl','--user','show-environment'],text=True);session={}
for line in envout.splitlines():
 if '=' in line:
  k,v=line.split('=',1)
  if k in ['DISPLAY','WAYLAND_DISPLAY','XAUTHORITY','LANG']:session[k]=v
cmd=pre+['systemd-run','--user','--collect','--unit=f8-sensor-relay-panel-toggle-live','--setenv=QT_QPA_PLATFORM=wayland']+['--setenv='+k+'='+v for k,v in session.items()]+['/usr/local/bin/f8-sensor-relay']
r=subprocess.run(cmd,capture_output=True,text=True,timeout=10)
print(json.dumps({'panel_exit':r.returncode,'panel_message':r.stderr,'snapshot':json.loads(Path('/run/user/1602/f8-sensor-relay.json').read_text())}))

time.sleep(2)
print(json.dumps({"panel_active":subprocess.run(pre+["systemctl","--user","is-active","f8-sensor-relay-panel-toggle-live.service"],capture_output=True,text=True).stdout.strip()}))
